use std :: collections :: HashMap ; use chrono :: { DateTime , Utc } ; use derive_setters :: Setters ; use serde :: { Deserialize , Serialize } ; use crate :: { AccessToken , ApiKey , OAuthConfig , ProviderId , RefreshToken , URLParam , URLParamValue } ; impl OAuthTokens { pub fn new (access_token : impl ToString , refresh_token : Option < impl ToString > , expires_at : DateTime < Utc > ,) -> Self { Self { access_token : access_token . to_string () . into () , refresh_token : refresh_token . map (| a | a . to_string () . into ()) , expires_at , } } # [doc = " Checks if the token is expired or will expire within the given buffer"] # [doc = " duration"] pub fn needs_refresh (& self , buffer : chrono :: Duration) -> bool { let now = Utc :: now () ; now + buffer >= self . expires_at } # [doc = " Checks if the token is currently expired"] pub fn is_expired (& self) -> bool { Utc :: now () >= self . expires_at } }